mapper.select:
SELECT w.warehouse_name as warehouseName, COUNT(DISTINCT i.product_id) as productCount, SUM(i.quantity) as totalQuantity, SUM(i.available_qty) as availableQuantity FROM wms_inventory i INNER JOIN wms_warehouse w ON i.warehouse_id = w.id
AND i.warehouse_id = #{warehouseId}
GROUP BY i.warehouse_id, w.warehouse_name
